sys_script_include.script:
var AccessGovernanceRevokeProcessor = Class.create();
AccessGovernanceRevokeProcessor.prototype = {
    initialize: function() {},
     processRequest:function(userId, action, groupsList, requestedBy, approvedBy, accessGovernanceId) {
        var res = {
            status: 'success',
            action: action,
            result: ''
        };
        // your branching logic here
        if (action == 'offboard_user') {
            var user = new GlideRecord('sys_user');
            user.addQuery('sys_id', userId);
            user.query();
            if (user.next()) {
                var username = user.name;
            }
            var gr1 = new GlideRecord('sys_user_grmember');
            gr1.addQuery('user', userId);
            gr1.query();
            while (gr1.next()) {
                var grname = gr1.group.getDisplayValue();
                var auditGr1 = new GlideRecord('x_2037341_access_0_audit_table'); //Creating GlideRecord Query to insert the auditing details into the audit table
                auditGr1.initialize();
                auditGr1.target_user = userId;
                auditGr1.revoke_type = 'Group';
                auditGr1.revoke_name = grname;
                auditGr1.reqested_by = requestedBy;
                auditGr1.approved_by = approvedBy;
                auditGr1.access_governance_id = accessGovernanceId;
                auditGr1.short_description = 'Revoked group ' + grname + ' from ' + username;
                auditGr1.date = new GlideDateTime();
                auditGr1.insert();
            }
            var userHasRole = new GlideRecord('sys_user_has_role');
            userHasRole.addQuery('user', userId);
            userHasRole.addQuery('inherited', false);
            userHasRole.query();
            while (userHasRole.next()) {
                var rolename = userHasRole.role.getDisplayValue();
                var auditGr2 = new GlideRecord('x_2037341_access_0_audit_table'); //Creating GlideRecord Query to insert the auditing details into the audit table
                auditGr2.initialize();
                auditGr2.target_user = userId;
                auditGr2.revoke_type = 'Role';
                auditGr2.revoke_name = rolename;
                auditGr2.reqested_by = requestedBy;
                auditGr2.approved_by = approvedBy;
                auditGr2.access_governance_id = accessGovernanceId;
                auditGr2.short_description = 'Revoked role ' + rolename + ' from ' + username;
                auditGr2.date = new GlideDateTime();
                auditGr2.insert();

            }

            var offboard = new global.AccessGovernanceGlobalHelper();
            var r = offboard.offboardUser(userId);
            res.result = r;
        } else if (action == 'revoke_roles_groups') {
            var user = new GlideRecord('sys_user');
            user.addQuery('sys_id', userId);
            user.query();
            if (user.next()) {
                var username = user.name;
            }
            var revoke = new global.AccessGovernanceGlobalHelper();
            var groupArray = groupsList.split(',');
            var resultarr = [];
            for (var i = 0; i < groupArray.length; i++) {
                var groupGr = new GlideRecord('sys_user_group');
                groupGr.addQuery('sys_id', groupArray[i]);
                groupGr.query();
                if (groupGr.next()) {
                    var groupname = groupGr.name;
                } else {
                    groupname = 'Unknown Group';
                }
                var auditGr = new GlideRecord('x_2037341_access_0_audit_table'); //Creating GlideRecord Query to insert the auditing details into the audit table
                auditGr.initialize();
                auditGr.target_user = userId;
                auditGr.revoke_type = 'Group';
                auditGr.revoke_name = groupname;
                auditGr.reqested_by = requestedBy;
                auditGr.approved_by = approvedBy;
                auditGr.access_governance_id = accessGovernanceId;
                auditGr.short_description = 'Revoked group ' + groupname + ' from ' + username;
                auditGr.date = new GlideDateTime();
                auditGr.insert();
                var rr = revoke.revokeGroupMembership(userId, groupArray[i]);
                resultarr.push(rr);
            }
            res.results = resultarr;



        } else if (action == 'review_roles_groups') {
            // No automated action for Review — security context already
            // captured at request-creation time via AccessGovernanceUtils

        } else {
            res.status = 'error';
            res.message = 'Unrecognized action: ' + action;
        }
        return res;
    },

    type: 'AccessGovernanceRevokeProcessor'
};
